#!/usr/bin/env python3
"""Fail a pull request that edits generated Go without a generator input.

A hand edit to a generated file is Speakeasy custom code. It survives only if a
regeneration observes it: `regenerate.yaml` is path-filtered to `.speakeasy/**`,
so a PR that touches generated Go alone never runs the generator, and the edit is
never validated against it. The breakage then lands on whatever unrelated PR
regenerates next, usually as an unused-function lint failure nobody can trace.

Setting `persistentEdits.enabled` is not enough on its own either: generation
lints the freshly generated tree before custom code is re-applied, so a helper
whose only caller is a custom-code line is dead code at generate time. That is a
review problem, not something this script can see.

Usage: check_generated_pairing.py <base-sha> <head-sha>
"""

from __future__ import annotations

import re
import subprocess
import sys

# Generated by Speakeasy, and the paths worth guarding: docs, README, RELEASES
# and examples are also tracked, but a human edit to prose is legitimate and
# harmless. Guard by suffix rather than by one directory, because the lock file
# also tracks generated Go outside internal/provider/ and internal/sdk/:
# internal/planmodifiers/, internal/validators/, main.go and tools/tools.go. The
# prefixes stay for files a pull request adds, which the head's lock file cannot
# list yet.
GUARDED_SUFFIX = ".go"
GUARDED_PREFIXES = ("internal/provider/", "internal/sdk/")

# Generated from the inputs on every run, so a change to them alone is not a
# declaration that the generator was consulted.
GENERATED_LOCKS = (
    ".speakeasy/gen.lock",
    ".speakeasy/workflow.lock",
    ".speakeasy/out.openapi.yaml",
)


def tracked_generated_files() -> set[str]:
    """Paths Speakeasy tracks, from the lock file it writes."""
    try:
        text = open(".speakeasy/gen.lock", encoding="utf-8").read()
    except FileNotFoundError:
        return set()
    block = text.split("\ntrackedFiles:\n", 1)
    if len(block) != 2:
        return set()
    # Tracked entries are the only keys at two-space indentation in the block.
    return set(re.findall(r"^  (\S.*?):$", block[1].split("\nexamples:", 1)[0], re.M))


def changed(base: str, head: str) -> list[tuple[str, str]]:
    """``(status, path)`` for both sides of every change, so moving a generated
    file out of a guarded path is still seen at the path it left.

    The status letter decides whether the path is *added* or merely edited, and
    the guard needs that distinction: a tracked generated file is guarded
    wherever it sits and however it is edited, while a guarded prefix is a
    stand-in for "this path is new, so the head's lock file cannot list it yet"
    and must not fire on an edit to a hand-written file that was already there.
    """
    out = subprocess.run(
        ["git", "diff", "--name-status", f"{base}...{head}"],
        capture_output=True, text=True, check=True,
    ).stdout
    entries: list[tuple[str, str]] = []
    for line in out.splitlines():
        # "<status>\t<path>" or "<status>\t<old>\t<new>" for renames and copies.
        fields = [field for field in line.split("\t") if field.strip()]
        if len(fields) < 2:
            continue
        status = fields[0].strip()[:1]
        for index, field in enumerate(fields[1:]):
            # A rename or copy carries old then new under one status letter: the
            # first path is never an addition (a copy leaves it in place), the
            # second arrives at that location.
            effective = status if len(fields) == 2 else ("A" if index else "D")
            entries.append((effective, field.strip()))
    return entries


def main() -> int:
    if len(sys.argv) != 3:
        print(__doc__)
        return 2
    base, head = sys.argv[1], sys.argv[2]

    files = changed(base, head)
    if not files:
        print("No changed files; nothing to check.")
        return 0

    tracked = tracked_generated_files()
    guarded = [
        f for status, f in files
        if f.endswith(GUARDED_SUFFIX)
        and (f in tracked or (status == "A" and f.startswith(GUARDED_PREFIXES)))
    ]
    if not guarded:
        return 0

    # `gen.yaml` counts even though regeneration rewrites it: it is also on
    # regenerate.yaml's path filter, so changing it is what makes a generation
    # observe the edit. The three lock/out files above are excluded because a
    # release bump alone touches them.
    # `gen.yaml` counts even though regeneration rewrites it: it is also on
    # regenerate.yaml's path filter, so changing it is what makes a generation
    # observe the edit. The three lock/out files above are excluded because a
    # release bump alone touches them.
    inputs = [
        f for _status, f in files
        if f.startswith(".speakeasy/") and f not in GENERATED_LOCKS
    ]
    if inputs:
        print("Generated code and a generator input both changed:")
        for f in sorted(guarded):
            print(f"  generated: {f}")
        for f in sorted(inputs):
            print(f"  input:     {f}")
        return 0

    print("::error::This pull request edits generated Go but no generator input.")
    print("")
    print("Speakeasy only replays a hand edit when a generation has observed it, and")
    print("`.github/workflows/regenerate.yaml` runs only for `.speakeasy/**` changes.")
    print("As it stands, the next unrelated PR that regenerates can drop these edits")
    print("and fail its own build. Changed generated files:")
    for f in sorted(guarded):
        print(f"  {f}")
    print("")
    print("Fix by declaring the edit: change a `.speakeasy/` input as well, usually a")
    print("comment in `speakeasy-modifications-overlay.yaml` explaining why the")
    print("generated code has to differ, so this PR regenerates and the regenerated")
    print("commit can be checked for the edit. If the edit adds a hand-written helper")
    print("whose only caller is inside a generated file, add the file-scoped")
    print("`//lint:file-ignore U1000` directive in the same PR: generation lints the")
    print("tree before custom code is re-applied, so the helper is dead code there.")
    return 1


if __name__ == "__main__":
    sys.exit(main())
